int ethiopian(int plier, int plicand, int tutor) {
    int result = 0;

    if (tutor) {
        printf("ethiopian multiplication of %d by %d\n", plier, plicand);
    }

    while (plier >= 1) {
        if (! (plier & 1)) {
            if (tutor) printf("%4d %6d struck\n", plier, plicand);
        } else {
            if (tutor) printf("%4d %6d kept\n", plier, plicand);
            result += plicand;
        }
        plier >>= 1; // Halve
        plicand <<= 1; // Double
    }

    return result;
}

