#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *list;
    short count;
} Factors;

void xferFactors(Factors *fctrs, int *flist, int flix) {
    int newSize = fctrs->count + flix;
    if (newSize > flix) {
        fctrs->list = realloc(fctrs->list, newSize * sizeof(int));
    } else {
        fctrs->list = malloc(newSize * sizeof(int));
    }
    for (int i = 0; i < flix; i++) {
        fctrs->list[fctrs->count + i] = flist[i];
    }
    fctrs->count = newSize;
}

Factors *factor(int num, Factors *fctrs) {
    int flist[301], flix = 0;
    for (int dvsr = 1; dvsr * dvsr <= num; dvsr++) {
        if (num % dvsr == 0) {
            if (flix == 300) {
                xferFactors(fctrs, flist, flix);
                flix = 0;
            }
            flist[flix++] = dvsr;
            if (dvsr != num / dvsr) {
                flist[flix++] = num / dvsr;
            }
        }
    }
    if (flix > 0) {
        xferFactors(fctrs, flist, flix);
    }
    return fctrs;
}

int main() {
    int nums2factor[] = { 2059, 223092870, 3135, 45 };
    Factors ftors = { NULL, 0 };

    for (int i = 0; i < 4; i++) {
        factor(nums2factor[i], &ftors);
        printf("\nfactors of %d are:\n  ", nums2factor[i]);
        char sep = ' ';
        for (int j = 0; j < ftors.count; j++) {
            printf("%c %d", sep, ftors.list[j]);
            sep = ',';
        }
        printf("\n");
    }

    free(ftors.list);
    return 0;
}

