template <class T>
int binsearch(const T array[], int low, int high, T value) {
    while (low <= high) {
        auto mid = low + (high - low) / 2;
        if (array[mid] == value) return mid;
        else if (value < array[mid]) high = mid - 1;
        else low = mid + 1;
    }
    return -1;
}

int main() {
    int array[] = {2, 3, 5, 6, 8};
    int result1 = binsearch(array, 0, sizeof(array)/sizeof(int) - 1, 4),
        result2 = binsearch(array, 0, sizeof(array)/sizeof(int) - 1, 8);

    if (result1 == -1) std::cout << "4 not found!" << std::endl;
    else std::cout << "4 found at " << result1 << std::endl;

    if (result2 == -1) std::cout << "8 not found!" << std::endl;
    else std::cout << "8 found at " << result2 << std::endl;

    return 0;
}

#include <iostream>
#include <string>

std::string caesarCipher(const std::string& text, int shift) {
    std::string result = text;
    for (char& c : result) {
        if (c >= 'a' && c <= 'z') {
            c = ((c - 'a' + shift) % 26 + 26) % 26 + 'a';
        } else if (c >= 'A' && c <= 'Z') {
            c = ((c - 'A' + shift) % 26 + 26) % 26 + 'A';
        }
    }
    return result;
}

int main() {
    std::string input;
    int myshift;

    std::cout << "Which text is to be encrypted? ";
    std::getline(std::cin, input);

    std::cout << "Shift? ";
    std::cin >> myshift;

    std::string encrypted = caesarCipher(input, myshift);
    std::string decrypted = caesarCipher(encrypted, -myshift);

    std::cout << "Before encryption:\n" << input << "\n";
    std::cout << "Encrypted:\n" << encrypted << "\n";
    std::cout << "Decrypted again:\n" << decrypted << "\n";

    return 0;
}

