// Function to generate and print all combinations of N items taken K at a time.
void generateCombinations(int totalItems, int combinationSize) {
    // Create a bitmask string with 'combinationSize' number of 1's followed by 'totalItems - combinationSize' number of 0's.
    std::string bitmask(combinationSize, '1'); // '1's represent selected items
    bitmask.append(totalItems - combinationSize, '0'); // '0's represent non-selected items

    // Print the initial combination and then generate all permutations by moving from largest to smallest.
    do {
        for (int i = 0; i < totalItems; ++i) {
            if (bitmask[i] == '1') { // If the current position is marked as selected, print the index.
                std::cout << " " << i;
            }
        }
        std::cout << std::endl; // Move to the next line after printing each combination.
    } while (std::prev_permutation(bitmask.begin(), bitmask.end())); // Generate permutations in lexicographical order.
}

int main() {
    generateCombinations(5, 3); // Example: Generate all combinations of 5 items taken 3 at a time.
    return 0;
}

