#include <stdio.h>
#include <string.h>

void reverse_string(char *str) {
    int len = strlen(str);
    for (int i = 0; i < len / 2; i++) {
        char temp = str[i];
        str[i] = str[len - i - 1];
        str[len - i - 1] = temp;
    }
}

int main(void) {
    const char *sa = "abcdef";
    const char *su = "as⃝df̅"; /* Should be in your native locale encoding. Mine is UTF-8 */

    // Create mutable copies of the strings
    char sa_copy[7]; // 6 characters + null terminator
    char su_copy[10]; // 9 characters + null terminator

    strcpy(sa_copy, sa);
    strcpy(su_copy, su);

    reverse_string(sa_copy);
    reverse_string(su_copy);

    printf("%s => %s\n", sa, sa_copy);
    printf("%s => %s\n", su, su_copy);

    return 0;
}

