int countSubstring(const std::string& str, const std::string& sub) {
    if (sub.empty()) return 0;

    int count = 0;
    for (size_t pos = str.find(sub); pos != std::string::npos; pos = str.find(sub, pos + sub.length())) {
        ++count;
    }
    return count;
}

