#include <algorithm>

std::vector<int> GenerateFactors(int n) {
    std::vector<int> factors;
    for (int i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            factors.push_back(i);
            if (i != n / i)
                factors.push_back(n / i);
        }
    }

    std::sort(factors.begin(), factors.end());
    return factors;
}

int main() {
    const int SampleNumbers[] = { 3135, 45, 60, 81 };

    for (int num : SampleNumbers) {
        std::vector<int> factors = GenerateFactors(num);
        std::cout << "Factors of " << num << " are: ";
        for (int factor : factors) {
            std::cout << factor << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}

