type caesarCipher struct {
	key int
}

func newCaesar(key int) (*caesarCipher, bool) {
	if key < 0 || key > 25 {
		return nil, false
	}
	return &caesarCipher{key}, true
}

func (c *caesarCipher) encipher(pt string) string {
	return strings.Map(func(r rune) rune {
		switch {
		case 'a' <= r && r <= 'z':
			return 'a' + (r-'a'+rune(c.key))%26
		case 'A' <= r && r <= 'Z':
			return 'A' + (r-'A'+rune(c.key))%26
		default:
			return r
		}
	}, pt)
}

func (c *caesarCipher) decipher(ct string) string {
	return strings.Map(func(r rune) rune {
		switch {
		case 'a' <= r && r <= 'z':
			return 'a' + (r-'a'-rune(c.key)+26)%26
		case 'A' <= r && r <= 'Z':
			return 'A' + (r-'A'-rune(c.key)+26)%26
		default:
			return r
		}
	}, ct)
}

func main() {
	pt := "The quick brown fox jumps over the lazy dog"
	fmt.Println("Plaintext:", pt)
	for _, key := range []int{0, 1, 7, 25, 26} {
		c, ok := newCaesar(key)
		if !ok {
			fmt.Println("Key", key, "invalid")
			continue
		}
		ct := c.encipher(pt)
		fmt.Println("Key", key)
		fmt.Println("  Enciphered:", ct)
		fmt.Println("  Deciphered:", c.decipher(ct))
	}
}

