func factors(n int64) []int64 {
	if n < 1 {
		return []int64{}
	}

	var result []int64
	for i := int64(1); i*i <= n; i++ {
		if n%i == 0 {
			result = append(result, i)
			if i != n/i {
				result = append(result, n/i)
			}
		}
	}
	return result
}

