enum class Fibonacci {
    ITERATIVE {
        override fun get(n: Int): Long = if (n < 2) n.toLong() else {
            var a = 0L
            var b = 1L
            repeat(n - 1) {
                val temp = a + b
                a = b
                b = temp
            }
            b
        }
    },
    RECURSIVE {
        private fun fibHelper(n: Int, a: Long, b: Long): Long = if (n == 0) a else fibHelper(n - 1, b, a + b)
        override fun get(n: Int): Long = fibHelper(n, 0L, 1L)
    },
    CACHING {
        private val cache: MutableMap<Int, Long> = mutableMapOf(0 to 0L, 1 to 1L)
        override fun get(n: Int): Long = if (n < 2) n.toLong() else cache.getOrPut(n) { this[n - 1] + this[n - 2] }
    };

    abstract operator fun get(n: Int): Long
}

