int isBalanced(const char *s, int len) {
    int balance = 0;
    for (int i = 0; i < len; ++i) {
        if (s[i] == '[')
            ++balance;
        else if (s[i] == ']')
            --balance;
        if (balance < 0)
            return 0;
    }
    return balance == 0;
}

void shuffle(char *s, int n) {
    for (int i = n - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        char temp = s[i];
        s[i] = s[j];
        s[j] = temp;
    }
}

void generateSequence(char *s, int n) {
    for (int i = 0; i < n; ++i)
        s[i] = '[';
    for (int i = n; i < 2 * n; ++i)
        s[i] = ']';
    shuffle(s, 2 * n);
}

void doSequence(int n) {
    char s[64];
    generateSequence(s, n);
    printf("'%s': %s\n", s, isBalanced(s, 2 * n) ? "True" : "False");
}

