#include <stdio.h>
#include <string.h>

int count_occurrences(const char *s, const char *p, int overlap) {
    if (*p == '\0') return 0; // Edge case: empty pattern

    int l = strlen(p);
    const char *current = s;
    int count = 0;

    while ((current = strstr(current, p)) != NULL) {
        count++;
        current += (overlap ? 1 : l);
    }

    return count;
}

