    printf("%d\n", count_occurrences("the three truths", "th", 0));
    printf("overlap:%d\n", count_occurrences("abababababa", "aba", 1));
    printf("not:    %d\n", count_occurrences("abababababa", "aba", 0));
    return 0;
}

#include <stdio.h>

int ethiopian(int plier, int plicand, int tutor) {
    int result = 0;

    if (tutor)
        printf("ethiopian multiplication of %d by %d\n", plier, plicand);

    while (plier >= 1) {
        if (plier & 1) { // Check if plier is odd
            if (tutor)
                printf("%4d %6d kept\n", plier, plicand);
            result += plicand;
        } else {
            if (tutor)
                printf("%4d %6d struck\n", plier, plicand);
        }
        plier >>= 1; // Halve the plier
        plicand <<= 1; // Double the plicand
    }
    return result;
}

