#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *list;
    short count; 
} Factors;

void xferFactors(Factors *fctrs, int *flist, int flix) {
    if (fctrs == NULL || flist == NULL || flix <= 0) return;

    int newSize = fctrs->count + flix;
    int *newList = realloc(fctrs->list, newSize * sizeof(int));
    if (newList == NULL) {
        fprintf(stderr, "Memory allocation failed in xferFactors.\n");
        return;
    }
    for (int ij = 0, ix = fctrs->count; ix < newSize; ij++, ix++) {
        newList[ix] = flist[ij];
    }
    fctrs->list = newList;
    fctrs->count = newSize;
}

Factors *factor(int num, Factors *fctrs) {
    if (num <= 0 || fctrs == NULL) return fctrs;

    int flist[301], flix = 0;
    int dvsr;

    free(fctrs->list);
    fctrs->list = NULL;
    fctrs->count = 0;

    for (dvsr = 1; dvsr * dvsr <= num; dvsr++) {
        if (num % dvsr != 0) continue;
        if (flix == 300) {
            xferFactors(fctrs, flist, flix);
            flix = 0;
        }
        flist[flix++] = dvsr;
        flist[flix++] = num / dvsr;
    }
    if (dvsr * dvsr == num && flix < 301) {
        flist[flix++] = dvsr;
    }
    xferFactors(fctrs, flist, flix);

    return fctrs;
}

int main(int argc, char* argv[]) {
    int nums2factor[] = { 2059, 223092870, 3135, 45 };
    Factors ftors = { NULL, 0};

    for (int i = 0; i < 4; i++) {
        factor(nums2factor[i], &ftors);
        printf("\nfactors of %d are:\n  ", nums2factor[i]);
        if (ftors.list != NULL) {
            char sep = ' ';
            for (int j = 0; j < ftors.count; j++) {
                printf("%c %d", sep, ftors.list[j]);
                sep = ',';
            }
            free(ftors.list);
            ftors.list = NULL;
        }
        printf("\n");
    }

    return 0;
}

