const char *sa = "abcdef";
const char *su = "as⃝df̅"; /* Should be in your native locale encoding. Mine is UTF-8 */

int is_comb(wchar_t c) {
    if (c >= 0x300 && c <= 0x36f) return 1;
    if (c >= 0x1dc0 && c <= 0x1dff) return 1;
    if (c >= 0x20d0 && c <= 0x20ff) return 1;
    if (c >= 0xfe20 && c <= 0xfe2f) return 1;
    return 0;
}

wchar_t* mb_to_wchar(const char *s) {
    if (!s) return NULL;

    size_t len = mbstowcs(NULL, s, 0);
    if (len == (size_t)-1) return NULL;

    wchar_t *u = malloc((len + 1) * sizeof(wchar_t));
    if (!u) return NULL;

    if (mbstowcs(u, s, len + 1) != len) {
        free(u);
        return NULL;
    }

    return u;
}

wchar_t* ws_reverse(const wchar_t* u) {
    if (!u) return NULL;

    size_t len = wcslen(u);
    wchar_t *out = malloc((len + 1) * sizeof(wchar_t));
    if (!out) return NULL;

    out[len] = L'\0';
    size_t j = 0;
    while (len) {
        size_t i = len - 1;
        while (i && is_comb(u[i])) i--;
        wcsncpy(out + j, u + i, len - i);
        j += len - i;
        len = i;
    }
    return out;
}

char *mb_reverse(const char *in) {
    if (!in) return NULL;

    wchar_t *u = mb_to_wchar(in);
    if (!u) return NULL;

    wchar_t *r = ws_reverse(u);
    free(u);
    if (!r) return NULL;

    size_t len = wcstombs(NULL, r, 0);
    if (len == (size_t)-1) {
        free(r);
        return NULL;
    }

    char *out = malloc((len + 1) * sizeof(char));
    if (!out) {
        free(r);
        return NULL;
    }

    if (wcstombs(out, r, len + 1) != len) {
        free(out);
        free(r);
        return NULL;
    }

    free(r);
    return out;
}

int main(void) {
    setlocale(LC_CTYPE, "");

    char *result = mb_reverse(sa);
    if (result) {
        printf("%s => %s\n", sa, result);
        free(result);
    } else {
        fprintf(stderr, "Error reversing string: %s\n", sa);
    }

    result = mb_reverse(su);
    if (result) {
        printf("%s => %s\n", su, result);
        free(result);
    } else {
        fprintf(stderr, "Error reversing string: %s\n", su);
    }

    return 0;
}

