std::string generate(int n, char left = '[', char right = ']') {
    std::string str(n, left);
    str.append(n, right);

    // Use a random device to seed the Mersenne Twister engine
    static std::random_device rd;
    static std::mt19937 g(rd());

    std::shuffle(str.begin(), str.end(), g);
    return str;
}

bool balanced(const std::string &str, char left = '[', char right = ']') {
    int count = 0;
    for (char c : str) {
        if (c == left)
            count++;
        else if (c == right)
            if (--count < 0) return false;
    }
    return count == 0;
}

