    std::string input;
    std::cout << "Which text is to be encrypted?\n";
    std::getline(std::cin, input);
    std::cout << "Shift value?\n";
    int shift = 0;
    std::cin >> shift;

    std::string encrypted = caesarCipher(input, shift);
    std::string decrypted = caesarCipher(encrypted, -shift);

    std::cout << "Before encryption:\n" << input << "\n";
    std::cout << "Encrypted:\n" << encrypted << "\n";
    std::cout << "Decrypted again:\n" << decrypted << "\n";

    return 0;
}

