template<int N>
struct Half {
    enum { Result = N >> 1 };
};

template<int N>
struct Double {
    enum { Result = N << 1 };
};

template<int N>
struct IsEven {
    static const bool Result = (N & 1) == 0;
};

template<int Multiplier, int Multiplicand, int RunningTotal = 0>
struct EthiopianMultiplication {
    enum { 
        Result = IsEven<Multiplier>::Result ? 
            EthiopianMultiplication<Half<Multiplier>::Result, Double<Multiplicand>::Result, RunningTotal>::Result :
            EthiopianMultiplication<Half<Multiplier>::Result, Double<Multiplicand>::Result, Multiplicand + RunningTotal>::Result
    };
};

template<int Multiplicand, int RunningTotal>
struct EthiopianMultiplication<0, Multiplicand, RunningTotal> {
    enum { Result = RunningTotal };
};

