std::vector<int> GenerateFactors(int n) {
    std::vector<int> factors = { 1, n };
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            factors.push_back(i);
            if (i * i != n)
                factors.push_back(n / i);
        }
    }

    std::sort(factors.begin(), factors.end());
    return factors;
}

void printFactors(int number, const std::vector<int>& factors) {
    std::cout << "Factors of ";
    std::cout.width(4);
    std::cout << number << " are: ";
    std::copy(factors.begin(), factors.end(), std::ostream_iterator<int>(std::cout, " "));
    std::cout << std::endl;
}

