    const int SampleNumbers[] = { 3135, 45, 60, 81 };

    for (size_t i = 0; i < sizeof(SampleNumbers) / sizeof(int); ++i) {
        printFactors(SampleNumbers[i], GenerateFactors(SampleNumbers[i]));
    }

    return EXIT_SUCCESS;
