using System;

public class Gray {
    public static ulong grayEncode(ulong n) {
        return n ^ (n >> 1);
    }

    public static ulong grayDecode(ulong n) {
        ulong mask;
        for (mask = n >> 1; mask != 0; mask >>= 1) {
            n ^= mask;
        }
        return n;
    }

    public static void Main(string[] args) {
        Console.WriteLine("Number\tBinary\tGray\tDecoded");

        try {
            for (ulong i = 0; i < 32; i++) {
                string binary = Convert.ToString((long)i, 2);
                ulong gray = grayEncode(i);
                string grayStr = Convert.ToString((long)gray, 2);
                ulong decoded = grayDecode(gray);

                if (i != decoded) {
                    Console.WriteLine($"Error: Decoded value {decoded} does not match original {i}");
                } else {
                    Console.WriteLine($"{i}\t{binary}\t{grayStr}\t{decoded}");
                }
            }
        } catch (Exception ex) {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}

