func testBalanced(s string) bool {
	open := 0
	for _, c := range s {
		switch c {
		case '[':
			open++
		case ']':
			if open == 0 {
				return false
			}
			open--
		default:
			return false
		}
	}
	return open == 0
}

func main() {
	for i := uint(0); i < 10; i++ {
		s := generate(i)
		fmt.Println(s, ": ", testBalanced(s))
	}
	fmt.Println("():", testBalanced("()"))
}

