func H(data string) (entropy float64) {
	if data == "" {
		return 0
	}
	counts := make([]int, 256)
	for i := range data {
		counts[data[i]]++
	}
	n := len(data)
	for _, count := range counts {
		if count > 0 {
			px := float64(count) / float64(n)
			entropy += -px * math.Log2(px)
		}
	}
	return entropy
}

