// enc converts a decimal number to its Gray code equivalent.
func enc(b int) int {
	return b ^ (b >> 1)
}

// dec converts a Gray code back to its decimal equivalent.
func dec(g int) (int, error) {
	if g < 0 {
		return 0, fmt.Errorf("negative input not allowed")
	}
	b := 0
	for ; g != 0; g >>= 1 {
		b ^= g
	}
	return b, nil
}

func main() {
	fmt.Println("decimal  binary   gray    decoded")
	for b := 0; b < 32; b++ {
		g := enc(b)
		d, err := dec(g)
		if err != nil {
			fmt.Printf("Error decoding %d: %v\n", g, err)
			continue
		}
		fmt.Printf("  %2d     %05b   %05b   %05b  %2d\n", b, b, g, d, d)
	}
}

