    // Checks if string literals and brackets are balanced in the expression.
    public static boolean areStringAndBracketsBalanced(String expr) {
        return isBalanced(expr, "'\"", "\\\\", "{([", "})]", true);
    }

    // General method to check if brackets are balanced.
    public static boolean isBalanced(String expr, String literals, String escapes, String openBrackets, String closeBrackets, boolean allowOtherChars) {
        boolean[] inLiteral = new boolean[literals.length()];
        Deque<Character> stack = new ArrayDeque<>();

        for (int i = 0; i < expr.length(); i++) {
            char currentChar = get(expr, i);

            // Check if we are inside a literal.
            int index;
            if ((index = indexOf(inLiteral, true)) != -1) {
                if (currentChar == get(literals, index) && get(expr, i - 1) != get(escapes, index)) {
                    inLiteral[index] = false; // Exit the literal.
                }
            } else if ((index = indexOf(literals, currentChar)) != -1) {
                inLiteral[index] = true; // Enter a new literal.
            } else if ((index = indexOf(openBrackets, currentChar)) != -1) {
                stack.push(get(closeBrackets, index)); // Push the matching closing bracket onto the stack.
            } else if (indexOf(closeBrackets, currentChar) != -1) {
                // Check for a mismatched closing bracket.
                if (stack.isEmpty() || stack.pop() != currentChar) {
                    return false;
                }
            } else if (!allowOtherChars) {
                return false; // Unrecognized character found.
            }
        }

        return stack.isEmpty(); // All brackets should be matched.
    }

    // Helper method to find the index of a boolean value in an array.
    static int indexOf(boolean[] array, boolean value) {
        for (int i = 0; i < array.length; i++) {
            if (array[i] == value) {
                return i;
            }
        }
        return -1;
    }

    // Helper method to find the index of a character in a string.
    static int indexOf(String str, char ch) {
        return str.indexOf(ch);
    }

    // Helper method to get a character from a string at a specific index.
    static char get(String str, int index) {
        return str.charAt(index);
    }

    public static void main(String[] args) {
        System.out.println("With areSquareBracketsBalanced:");
        for (String s : new String[]{"", "[]", "[][]", "[[][]]", "][", "][][", "[]][[]", "[", "]"}) {
            System.out.printf("%s: %s\n", s, areSquareBracketsBalanced(s));
        }

        System.out.println("\nBut also with areStringAndBracketsBalanced:");
        for (String s : new String[]{"x[]", "[x]", "[]x", "([{}])", "([{}]()", "([{ '([{\\'([{' \"([{\\\"([{\" }])"}) {
            System.out.printf("%s: %s\n", s, areStringAndBracketsBalanced(s));
        }
    }
}

public class BinarySearch {
    public static int binarySearch(int[] nums, int target) {
        int left = 0;
        int right = nums.length - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] == target) {
                return mid;
            } else if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return -1;
    }

    public static void main(String[] args) {
        int[] haystack = {1, 5, 6, 7, 8, 11};
        int needle = 5;
        int index = binarySearch(haystack, needle);

        if (index == -1) {
            System.out.println(needle + " is not in the array");
        } else {
            System.out.println(needle + " is at index " + index);
        }
    }
}

public class Cipher {
    public static void main(String[] args) {
        String str = "The quick brown fox Jumped over the lazy Dog";

        System.out.println(encode(str, 12));
        System.out.println(decode(encode(str, 12), 12));
    }

    public static String decode(String enc, int offset) {
        return encode(enc, 26 - offset);
    }

    public static String encode(String enc, int offset) {
        StringBuilder encoded = new StringBuilder();
        for (char c : enc.toCharArray()) {
            if (Character.isLetter(c)) {
                char base = Character.isUpperCase(c) ? 'A' : 'a';
                encoded.append((char) ((c - base + offset) % 26 + base));
            } else {
                encoded.append(c);
            }
        }
        return encoded.toString();
    }
}

import java.util.ArrayList;
import java.util.List;

public final class Combinations {

    public static void main(String[] args) {
        System.out.println(createCombinations(List.of(0, 1, 2, 3, 4), 3));
        System.out.println(createCombinations(List.of("Crosby", "Nash", "Stills", "Young"), 3));
    }

    private static <T> List<List<T>> createCombinations(List<T> elements, int k) {
        List<List<T>> combinations = new ArrayList<>();
        combine(elements, k, 0, new ArrayList<>(), combinations);
        return combinations;
    }

    private static <T> void combine(List<T> elements, int k, int start, List<T> current, List<List<T>> result) {
        if (current.size() == k) {
            result.add(new ArrayList<>(current));
            return;
        }
        for (int i = start; i <= elements.size() - k + current.size(); i++) {
            current.add(elements.get(i));
            combine(elements, k, i + 1, current, result);
            current.remove(current.size() - 1);
        }
    }
}

