fun countSubstring(s: String, sub: String): Int {
    if (sub.isEmpty()) return 0
    var count = 0
    var index = s.indexOf(sub)

    while (index != -1) {
        count++
        index = s.indexOf(sub, index + sub.length)
    }

    return count
}

fun main() {
