fun log2(d: Double): Double {
    return if (d > 0) Math.log(d) / Math.log(2.0) else 0.0
}

fun shannon(s: String?): Double {
    if (s == null || s.isEmpty()) return 0.0

    val counters = mutableMapOf<Char, Int>()
    for (c in s) {
        counters[c] = counters.getOrDefault(c, 0) + 1
    }

    val nn = s.length.toDouble()
    var sum = 0.0
    for (count in counters.values) {
        val term = count / nn
        sum += term * log2(term)
    }
    return -sum
}

