fun ethiopianMultiply(n: Int, m: Int): Int {
    var result = 0
    var a = n
    var b = m

    while (a >= 1) {
        if (a % 2 == 1) {
            result += b
        }
        a /= 2
        b *= 2
    }

    return result
}

