enum class Fibonacci {
    ITERATIVE {
        override fun get(n: Int): Long = if (n < 2) n.toLong() else {
            var a = 0L
            var b = 1L
            repeat(n - 1) {
                val temp = a + b
                a = b
                b = temp
            }
            b
        }
    },
    RECURSIVE {
        override fun get(n: Int): Long = if (n < 2) n.toLong() else this[n - 1] + this[n - 2]
    },
    CACHING {
        private val cache = mutableMapOf(0 to 0L, 1 to 1L)
        override fun get(n: Int): Long = cache.getOrPut(n) { this[n - 1] + this[n - 2] }
    };

    abstract operator fun get(n: Int): Long
}

