function binary_search($array, $secret) {
    $start = 0;
    $end = count($array) - 1;

    while ($start <= $end) {
        $guess = (int)(($start + $end) / 2);

        if ($array[$guess] === $secret) {
            return $guess;
        }

        if ($array[$guess] > $secret) {
            $end = $guess - 1;
        } else {
            $start = $guess + 1;
        }
    }

    return -1;
}

function getFactors($n) {
    $factors = [];
    $sqrtN = sqrt($n);

    for ($i = 1; $i <= $sqrtN; $i++) {
        if ($n % $i == 0) {
            $factors[] = $i;
            if ($i != $n / $i) {
                $factors[] = $n / $i;
            }
        }
    }

    sort($factors);
    return $factors;
}

