from math import log2

def entropy(source):
    length = len(source)
    hist = {}

    for char in source:
        if char in hist:
            hist[char] += 1
        else:
            hist[char] = 1

    total_entropy = 0.0
    for count in hist.values():
        probability = count / length
        total_entropy -= probability * log2(probability)

    return total_entropy

