fn dot_product(a: &[i32], b: &[i32]) -> Option<i32> {
    if a.len() != b.len() { return None; }

    let mut sum = 0;
    for (el_a, el_b) in a.iter().zip(b.iter()) {
        sum += el_a * el_b;
    }

    Some(sum)
}

