fn ethiopian_multiplication(x: i32, y: i32) -> Result<i32, String> {
    if x < 0 || y < 0 {
        return Err("Inputs must be non-negative integers.".to_string());
    }

    let mut sum = 0;
    let mut a = x;
    let mut b = y;

    while a >= 1 {
        print!("{} \t {}", a, b);
        if is_even(a) {
            println!("\t Not Kept");
        } else {
            println!("\t Kept");
            sum += b;
        }
        a = halve(a);
        b = double(b);
    }

    Ok(sum)
}

