fn factor(num: i32) -> Vec<i32> {
    let mut factors = Vec::new();
    let sqrt_num = (num as f32).sqrt() as i32;

    for i in 1..=sqrt_num {
        if num % i == 0 {
            factors.push(i);
            if i != num / i {
                factors.push(num / i);
            }
        }
    }

    factors.sort_unstable();
    factors
}

