func binarySearch<T: Comparable>(_ xs: [T], _ x: T) -> Int? {
    var low = 0
    var high = xs.count - 1

    while low <= high {
        let mid = (low + high) / 2
        if xs[mid] > x {
            high = mid - 1
        } else if xs[mid] < x {
            low = mid + 1
        } else {
            return mid
        }
    }

    return nil
}

func caesar(_ enc: Bool, _ key: Int, _ word: String) -> String {
    let r = enc ? key : 27 - key
    var result = ""
    result.reserveCapacity(word.count)

    for c in word {
        if c.isLowercase || c == "-" {
            let cv = UInt8(c.asciiValue!)
            let rotated = (cv + UInt8(r) - 97) % 26 + 97
            result.append(Character(UnicodeScalar(rotated)))
        } else {
            result.append(c)
        }
    }

    return result
}

func main() {
    var encrypt = true

    if CommandLine.arguments.count != 4 {
        print("error: caesar expects exactly three arguments")
        print("./caeser -e 19 a-secret-string")
        print("./caeser -d 19 tskxvjxlskljafz")
        return
    }

    switch CommandLine.arguments[1] {
    case "-e":
        encrypt = true
    case "-d":
        encrypt = false
    default:
        print("error: first argument must be -e (encrypt) or -d (decrypt)")
        return
    }

    guard let key = Int(CommandLine.arguments[2]), key >= 0, key <= 26 else {
        print("error: second argument not a number (must be in range 0-26)")
        return
    }

    if !CommandLine.arguments[3].allSatisfy({ $0.isLowercase || $0 == "-" }) {
        print("error: third argument must only be lowercase ascii characters, or -")
        return
    }

    let ans = caesar(encrypt, key, CommandLine.arguments[3])
    print(ans)
}

