import Foundation

func entropy(of x: String) -> Double {
  let frequency = x.reduce(into: [Character: Int]()) { $0[$1, default: 0] += 1 }
  return frequency.values.map { Double($0) / Double(x.count) }
                      .map { -($0 * log2($0)) }
                      .reduce(0.0, +)
}

