struct GrayCode {
    var value: Int

    func encode() -> Int {
        return (value >> 1) ^ value
    }

    static func decode(_ grayValue: Int) -> Int {
        switch grayValue {
        case 0:
            return 0
        default:
            return grayValue ^ GrayCode.decode(grayValue >> 1)
        }
    }
}

for i in 0..<32 {
    let gray = GrayCode(value: i)
    let encode = gray.encode()
    let decode = GrayCode.decode(encode)

    print("\(i) (\(String(i, radix: 2))) => \(encode) (\(String(encode, radix: 2))) => \(decode) (\(String(decode, radix: 2)))")
}
